 add('line-long-arc',line([[0,0],[120,0]]));add('line-antimeridian',line([[170,20],[-170,20]]),'checked-finite-canonical',[[170,20],[-170,20],[180,20],[180,20.283559454529712],[0,0]]);add('line-antipodal',line([[0,0],[180,0]]),'checked-error-antipodal-edge');add('line-near-antipodal',line([[0,0],[180-1e-8,0]]),'checked-error-near-antipodal-edge');
 add('multiline',{type:'MultiLineString',coordinates:[[[0,0],[90,0]],[],[[170,20],[-170,20]]]});add('polygon',polygon([ring]));add('polygon-reversed',polygon([ring.slice().reverse()]));add('polygon-hole',polygon([ring,hole]));add('polygon-hole-reversed',polygon([ring,hole.slice().reverse()]));
