 add('polygon-antimeridian',polygon([[[170,-20],[170,20],[-170,20],[-170,-20],[170,-20]]]));add('polygon-north-pole',polygon([[[-180,80],[-60,80],[60,80],[180,80],[-180,80]]]));add('polygon-south-pole',polygon([[[-180,-80],[180,-80],[60,-80],[-60,-80],[-180,-80]]]));
