 add('sphere-point-fallback',collection([{type:'Sphere'},point([20,30])]));add('line-over-point-fallback',collection([point([-100,-40]),line([[0,0],[90,0]])]));add('area-over-line-fallback',collection([line([[-100,-40],[-90,-40]]),polygon([ring])]));add('collection',collection([null,point([0,0]),line([[0,0],[90,0]]),polygon([ring,hole])]));add('collection-empty',collection([]));
