 const files={'geometry-centroid.json':json({scope:'Original centroid values and input geometries; NaN remains tagged, never silently replaced with None',geometries,unexecuted:[{id:'source-over100000',profile:'checked-error-source-budget',specification:{type:'MultiPoint',repeat:[0,0],count:100001}}]})+'\n','contains.json':json(queries)+'\n','centroid-values.csv':geometries.map(c=>[c.id,c.profile,c.nativeCentroid].map(json).join('|')).join('\n')+'\n','contains-values.csv':queries.map(c=>[c.id,c.profile,c.point,c.nativeContains].map(json).join('|')).join('\n')+'\n'};
 return {files,counts:{geometries:geometries.length,containsQueries:queries.length,undefinedNativeCentroids:geometries.filter(c=>c.nativeCentroid.some(v=>!Number.isFinite(v))).length,intendedOrdinaryVectorTolerance:1e-12,containsComparison:'exact boolean, original epsilon1e-6/epsilon2=1e-12 semantics, no relaxed boundary'} };
